#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_TEXT_LEN 1024

static void print_usage(void) {
    puts("USAGE");
}

static int normalise_shift(long v) {
    int r = (int)(v % 26);
    if (r < 0) r += 26;
    return r;
}

static char shift_char(char c, int shift) {
    if ('A' <= c && c <= 'Z')
        return (char)('A' + (c - 'A' + shift) % 26);
    if ('a' <= c && c <= 'z')
        return (char)('a' + (c - 'a' + shift) % 26);
    return c;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        print_usage();
        return 0;
    }
    char *endptr;
    long raw_shift = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        print_usage();
        return 0;
    }
    int shift = normalise_shift(raw_shift);
    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > MAX_TEXT_LEN) {
        print_usage();
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        putchar(shift_char(text[i], shift));
    }
    putchar('\n');
    return 0;
}
